      s += (joint ? a + b - a * b : a) / Math.pow(1 + i, k);
    }
    return s;
  }
  function amortFactor(n, i) { return i === 0 ? n : (1 - Math.pow(1 + i, -n)) / i; }

  // Month index helpers: idx = year * 12 + (month - 1).
  function monthText(idx) { return MONTHS[idx % 12] + ' ' + Math.floor(idx / 12); }
  function period(birthIdx, firstIdx) {
