    set('swEndSwitch', switching ? fmt(r.endSw) : '–');
    set('swFive', monthText(per.five));
    set('swHalf', monthText(per.half));
    set('swUntil', monthText(per.until));
    set('swCount', per.count + ' (' + monthText(firstIdx) + ' to ' + monthText(firstIdx + (per.count - 1) * 12) + ')');
