    set('swTotalSwitch', switching ? fmt(r.totSw) : '–');
    var note = document.getElementById('swNote'), msg = '';
    if (switchYear > per.count) msg = 'Payment year ' + switchYear + ' is after the schedule ends, so no switch is needed: you can change or stop the payments then.';
    else if (r.stayOut && !(switching && !r.swOut)) msg = 'At these returns the fixed payment empties the account before the period ends. Running out isn’t a change, so the 10% doesn’t come back, but the money is gone.';
    else if (r.stayOut) msg = 'At these returns the fixed payment empties the account before the period ends; switching to the RMD method keeps money in it.';
    else if (switching) msg = 'After the switch the payment is recalculated every year from the December 31 balance, so it rises and falls with the account. You can’t switch back.';
    note.hidden = msg === '';
