    var rateNote = document.getElementById('swRateNote');
    rateNote.hidden = !(rate > SAFE_HARBOR_RATE);
    if (rate > SAFE_HARBOR_RATE) set('swRateNote', 'A rate above ' + SAFE_HARBOR_RATE + '% is allowed only if 120% of the federal mid-term rate ' +
        'for either of the two months before your first payment is at least that high.');
