    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.n, fy + row.n - 1, row.age, fmt(row.payS), fmt(row.stay), fmt(row.paySw) + (switching && row.rmd ? ' (RMD)' : ''),
       fmt(row.sw)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = String(v); tr.appendChild(td);
      });
      body.appendChild(tr);
    });
